    if (pendingChallengeIds.length) findings.push({ code: "RECOVERY_GATE_BATCH236_RECOVERY_PENDING", challengeIds: pendingChallengeIds });
    if (!checkpointCurrent) findings.push({ code: "RECOVERY_GATE_BATCH236_CHECKPOINT_NOT_CURRENT" });
    if (terminalRevocation) findings.push({ code: "RECOVERY_GATE_BATCH236_TERMINAL_REVOCATION", finalizationEventId: terminalRevocation.id });
    if (keyCutoffDetected && !keyCutoffRevalidated) findings.push({ code: "RECOVERY_GATE_BATCH236_KEY_CUTOFF_REVALIDATION_REQUIRED" });
