      pendingChallengeIds, invalidSignatureCount, keyCutoffDetected, keyCutoffRevalidated, terminalRevocation: terminalRevocation
        ? { id: terminalRevocation.id, digest: terminalRevocation.digest, generation: terminalRevocation.generation } : null,
      latestLifecycleEvent: latestLifecycleEvent ? { id: latestLifecycleEvent.id, digest: latestLifecycleEvent.digest,
        generation: latestLifecycleEvent.generation, action: latestBinding.action || null } : null,
