    assertOwner(ownerId);
    let ledger = await readLedger(ownerId);
    if (ledger.status === "unhealthy") throw new AgenticError("RECOVERY_GATE_PROOF_CONTINUITY_LEDGER_UNHEALTHY",
      "Tidak dapat membuat Batch 237 receipt dari ledger yang tidak sehat", 409, { findings: ledger.findings });
    const sourceAudit = await auditFinalizationReceiptBindingAttestationLifecycleExternalFinalizationReceiptAttestationLifecycle(ownerId);
    const finalizations = ledger.events.filter(event => event.eventType === FINALIZATION_RECEIPT_BINDING_ATTESTATION_LIFECYCLE_EXTERNAL_FINALIZATION_RECEIPT_ATTESTATION_LIFECYCLE_FINALIZED_EVENT)
