        targetAttestationId: intent.stableBinding.targetAttestationId, targetAttestationDigest: intent.stableBinding.targetAttestationDigest,
        sourceAttestationId: intent.stableBinding.sourceAttestationId, sourceAttestationDigest: intent.stableBinding.sourceAttestationDigest,
        sourceFinalizationReceiptId: intent.stableBinding.sourceFinalizationReceiptId,
        sourceFinalizationReceiptDigest: intent.stableBinding.sourceFinalizationReceiptDigest,
        intentEventId: intent.id, intentEventDigest: intent.digest, actionEventId: actionEvent.id, actionEventDigest: actionEvent.digest,
        renewedEventId: binding.action === "renew" ? renewed.id : null, renewedEventDigest: binding.action === "renew" ? renewed.digest : null,
        supersessionEventId: binding.action === "renew" ? supersession.id : null,
        supersessionEventDigest: binding.action === "renew" ? supersession.digest : null,
        replacementAttestationId: binding.action === "renew" ? renewed.id : null,
        replacementAttestationDigest: binding.action === "renew" ? renewed.digest : null,
        reasonDigest: intent.stableBinding.reasonDigest,
        lifecycleAuditDigest: sha256(canonical(lifecycleEvents.map(event => ({ id: event.id, digest: event.digest, eventType: event.eventType })))),
        lifecycleSigningKeyBindingDigest, receiptSigningKeyBindingDigest, keyCutoffDetected, keyCutoffRevalidated,
        sourceCheckpointFingerprint: finalized.checkpointFingerprint,
