      const operationId = `batch237-external-finalization-receipt-attestation-lifecycle:${finalized.id}:${finalized.digest}`;
      const appended = await appendEvent(ownerId, { eventType: FINALIZATION_RECEIPT_BINDING_ATTESTATION_LIFECYCLE_EXTERNAL_FINALIZATION_RECEIPT_ATTESTATION_LIFECYCLE_FINALIZATION_RECEIPT_EVENT,
        stable, operationId, generation: finalized.generation, allowKeyCutoffReplay: true });
