      const renewed = lifecycleEvents.find(event => event.eventType === FINALIZATION_RECEIPT_BINDING_ATTESTATION_LIFECYCLE_EXTERNAL_FINALIZATION_RECEIPT_ATTESTATION_LIFECYCLE_RENEWED_EVENT) || null;
      const revoked = lifecycleEvents.find(event => event.eventType === FINALIZATION_RECEIPT_BINDING_ATTESTATION_LIFECYCLE_EXTERNAL_FINALIZATION_RECEIPT_ATTESTATION_LIFECYCLE_REVOKED_EVENT) || null;
      const supersession = lifecycleEvents.find(event => event.eventType === FINALIZATION_RECEIPT_BINDING_ATTESTATION_LIFECYCLE_EXTERNAL_FINALIZATION_RECEIPT_ATTESTATION_LIFECYCLE_SUPERSESSION_EVENT) || null;
      const actionEvent = finalizedBinding.action === "renew" ? supersession : revoked;
