    let ledger = await readLedger(ownerId);
    if (ledger.status === "unhealthy") throw new AgenticError("RECOVERY_GATE_PROOF_CONTINUITY_LEDGER_UNHEALTHY",
      "Tidak dapat membuat Batch 234 finalization receipt dari ledger yang tidak sehat", 409, { findings: ledger.findings });
    const sourceAudit = await auditFinalizationReceiptBindingAttestationLifecycleExternalLifecycleFinalizationReceiptAttestationLifecycle(ownerId);
    if (sourceAudit.status === "unhealthy") throw new AgenticError("RECOVERY_GATE_BATCH234_SOURCE_LIFECYCLE_UNHEALTHY",
      "Batch 233 lifecycle chain tidak sehat; Batch 234 receipt ditolak", 409, { findings: sourceAudit.findings || [] });
