      const intent = lifecycleEvents.find(event => event.eventType === FINALIZATION_RECEIPT_BINDING_ATTESTATION_LIFECYCLE_EXTERNAL_LIFECYCLE_FINALIZATION_RECEIPT_ATTESTATION_INTENT_EVENT) || null;
      const action = finalized.stableBinding?.action;
