      const revoked = lifecycleEvents.find(event => event.eventType === FINALIZATION_RECEIPT_BINDING_ATTESTATION_LIFECYCLE_EXTERNAL_LIFECYCLE_FINALIZATION_RECEIPT_ATTESTATION_REVOKED_EVENT) || null;
      const supersession = lifecycleEvents.find(event => event.eventType === FINALIZATION_RECEIPT_BINDING_ATTESTATION_LIFECYCLE_EXTERNAL_LIFECYCLE_FINALIZATION_RECEIPT_ATTESTATION_SUPERSESSION_EVENT) || null;
