        targetAttestationDigest: intent.stableBinding?.targetAttestationDigest || null,
        sourceAttestationId: intent.stableBinding?.sourceAttestationId || null,
        sourceAttestationDigest: intent.stableBinding?.sourceAttestationDigest || null,
        sourceFinalizationReceiptId: intent.stableBinding?.sourceFinalizationReceiptId || null,
        sourceFinalizationReceiptDigest: intent.stableBinding?.sourceFinalizationReceiptDigest || null,
