        supersessionEventId: action === "renew" ? supersession.id : null, supersessionEventDigest: action === "renew" ? supersession.digest : null,
        replacementAttestationId: action === "renew" ? renewed.id : null, replacementAttestationDigest: action === "renew" ? renewed.digest : null,
