      const checkpointFingerprintValue = sha256(canonical({ domain: "batch234-external-lifecycle-finalization-receipt", ...provisional, receiptBindingDigest }));
      const stable = { ...provisional, receiptBindingDigest, checkpointFingerprint: checkpointFingerprintValue };
      const operationId = `batch234-external-lifecycle-finalization-receipt:${finalized.id}:${finalized.digest}`;
      const appended = await appendEvent(ownerId, { eventType: FINALIZATION_RECEIPT_BINDING_ATTESTATION_LIFECYCLE_EXTERNAL_LIFECYCLE_FINALIZATION_RECEIPT_ATTESTATION_FINALIZATION_RECEIPT_EVENT,
        stable, operationId, generation: finalized.generation, allowKeyCutoffReplay: true });
