      const finalized = finalizations.find(event => event.id === binding.lifecycleFinalizationEventId
        && event.digest === binding.lifecycleFinalizationEventDigest && event.generation === receipt.generation) || null;
      const challengeEvents = ledger.events.filter(event => BATCH233_EVENT_TYPES.includes(event.eventType)
        && event.stableBinding?.challengeId === binding.challengeId);
      const intent = challengeEvents.find(event => event.eventType === FINALIZATION_RECEIPT_BINDING_ATTESTATION_LIFECYCLE_EXTERNAL_LIFECYCLE_FINALIZATION_RECEIPT_ATTESTATION_INTENT_EVENT) || null;
      const renewed = challengeEvents.find(event => event.eventType === FINALIZATION_RECEIPT_BINDING_ATTESTATION_LIFECYCLE_EXTERNAL_LIFECYCLE_FINALIZATION_RECEIPT_ATTESTATION_RENEWED_EVENT) || null;
      const revoked = challengeEvents.find(event => event.eventType === FINALIZATION_RECEIPT_BINDING_ATTESTATION_LIFECYCLE_EXTERNAL_LIFECYCLE_FINALIZATION_RECEIPT_ATTESTATION_REVOKED_EVENT) || null;
      const supersession = challengeEvents.find(event => event.eventType === FINALIZATION_RECEIPT_BINDING_ATTESTATION_LIFECYCLE_EXTERNAL_LIFECYCLE_FINALIZATION_RECEIPT_ATTESTATION_SUPERSESSION_EVENT) || null;
      const actionEvent = binding.action === "renew" ? supersession : revoked;
      const sourceAttestation = ledger.events.find(event => event.id === binding.sourceAttestationId
        && event.digest === binding.sourceAttestationDigest && BATCH232_EVENT_TYPES.includes(event.eventType)) || null;
      const sourceReceipt = ledger.events.find(event => event.id === binding.sourceFinalizationReceiptId
        && event.digest === binding.sourceFinalizationReceiptDigest && BATCH231_EVENT_TYPES.includes(event.eventType)) || null;
      const expectedAuditDigest = sha256(canonical(challengeEvents.map(event => ({ id: event.id, digest: event.digest, eventType: event.eventType }))));
      const expectedBindingDigest = sha256(canonical(batch234LifecycleFinalizationReceiptBindingFields(binding)));
      const expectedFingerprint = sha256(canonical({ domain: "batch234-external-lifecycle-finalization-receipt",
        ...batch234LifecycleFinalizationReceiptBindingFields(binding), receiptBindingDigest: binding.receiptBindingDigest }));
      const invalid = !finalized || !intent || !actionEvent || seenFinalizations.has(finalized?.id)
        || receipt.generation !== index + 1 || binding.lifecycleFinalizationReceiptGeneration !== receipt.generation
        || (binding.previousReceiptId || null) !== (previous?.id || null) || (binding.previousReceiptDigest || null) !== (previous?.digest || null)
        || binding.challengeId !== finalized?.stableBinding?.challengeId || binding.action !== finalized?.stableBinding?.action
        || binding.externalAttestationLifecycleGeneration !== finalized?.stableBinding?.externalAttestationLifecycleGeneration
        || binding.targetAttestationId !== intent?.stableBinding?.targetAttestationId || binding.targetAttestationDigest !== intent?.stableBinding?.targetAttestationDigest
        || binding.sourceAttestationId !== intent?.stableBinding?.sourceAttestationId || binding.sourceAttestationDigest !== intent?.stableBinding?.sourceAttestationDigest
        || binding.sourceFinalizationReceiptId !== intent?.stableBinding?.sourceFinalizationReceiptId
        || binding.sourceFinalizationReceiptDigest !== intent?.stableBinding?.sourceFinalizationReceiptDigest
        || !sourceAttestation || !sourceReceipt
        || sourceAttestation.stableBinding?.finalizationReceiptId !== sourceReceipt.id
        || sourceAttestation.stableBinding?.finalizationReceiptDigest !== sourceReceipt.digest
        || binding.intentEventId !== intent?.id || binding.intentEventDigest !== intent?.digest
        || binding.actionEventId !== actionEvent?.id || binding.actionEventDigest !== actionEvent?.digest
        || binding.reasonDigest !== intent?.stableBinding?.reasonDigest || binding.lifecycleAuditDigest !== expectedAuditDigest
        || binding.lifecycleSigningKeyBindingDigest !== finalized?.keyLifecycleBindingDigest
        || binding.receiptSigningKeyBindingDigest !== receipt.keyLifecycleBindingDigest
        || binding.sourceCheckpointFingerprint !== finalized?.checkpointFingerprint
        || binding.receiptBindingDigest !== expectedBindingDigest || receipt.checkpointFingerprint !== expectedFingerprint
        || binding.bindingDigest && binding.bindingDigest !== expectedBindingDigest
        || binding.action === "renew" && (binding.renewedEventId !== renewed?.id || binding.renewedEventDigest !== renewed?.digest
          || binding.supersessionEventId !== supersession?.id || binding.supersessionEventDigest !== supersession?.digest
          || binding.replacementAttestationId !== renewed?.id || binding.replacementAttestationDigest !== renewed?.digest)
        || binding.action === "revoke" && (binding.renewedEventId || binding.supersessionEventId || binding.replacementAttestationId || binding.replacementAttestationDigest);
      if (invalid) { chainInvalid = true; findings.push({ code: "RECOVERY_GATE_BATCH234_RECEIPT_BINDING_INVALID", receiptId: receipt.id, generation: receipt.generation }); }
