      lifecycleFinalizationEventId: binding.lifecycleFinalizationEventId || null,
      lifecycleFinalizationEventDigest: binding.lifecycleFinalizationEventDigest || null,
      challengeId: binding.challengeId || null,
      action: binding.action || null,
      targetAttestationId: binding.targetAttestationId || null,
      targetAttestationDigest: binding.targetAttestationDigest || null,
      sourceAttestationId: binding.sourceAttestationId || null,
      sourceAttestationDigest: binding.sourceAttestationDigest || null,
