      targetAttestationDigest: binding.targetAttestationDigest || null,
      sourceAttestationId: binding.sourceAttestationId || null,
      sourceAttestationDigest: binding.sourceAttestationDigest || null,
      sourceFinalizationReceiptId: binding.sourceFinalizationReceiptId || null,
      sourceFinalizationReceiptDigest: binding.sourceFinalizationReceiptDigest || null,
      intentEventId: binding.intentEventId || null,
      intentEventDigest: binding.intentEventDigest || null,
      actionEventId: binding.actionEventId || null,
      actionEventDigest: binding.actionEventDigest || null,
      replacementAttestationId: binding.replacementAttestationId || null,
      replacementAttestationDigest: binding.replacementAttestationDigest || null,
      receiptBindingDigest: binding.receiptBindingDigest || null,
      sourceReceiptChainDigest: binding.sourceReceiptChainDigest || null,
      sourceCheckpointFingerprint: binding.sourceCheckpointFingerprint || null,
      sourceLifecycleAuditDigest: binding.sourceLifecycleAuditDigest || null,
      sourceSigningKeyLifecycleBindingDigest: binding.sourceSigningKeyLifecycleBindingDigest || null,
      signingKeyLifecycleBindingDigest: binding.signingKeyLifecycleBindingDigest || null,
      keyCutoffDetected: binding.keyCutoffDetected === true,
