    if (sourceAudit.status === "unhealthy") throw new AgenticError("RECOVERY_GATE_BATCH248_SOURCE_RECEIPTS_UNHEALTHY",
      "Batch 247 lifecycle finalization receipt chain tidak sehat; external attestation ditolak", 409,
      { findings: sourceAudit.findings || [] });
