      createdCount, reusedCount, complete: audit.missingAttestationCount === 0
        && (audit.usableForCurrentDecision === true || audit.status === "decision_blocked"),
      latestAttestation: attestations.length ? { id: attestations.at(-1).id, digest: attestations.at(-1).digest,
        generation: attestations.at(-1).generation, operationId: attestations.at(-1).operationId } : null,
