        intentEventDigest: source.intentEventDigest, actionEventId: source.actionEventId, actionEventDigest: source.actionEventDigest,
        replacementAttestationId: source.replacementAttestationId || null, replacementAttestationDigest: source.replacementAttestationDigest || null,
        receiptBindingDigest: source.receiptBindingDigest, sourceReceiptChainDigest, sourceCheckpointFingerprint,
