      const operationId = `batch252-external-attestation:${receipt.id}:${bindingDigest}:${latestAttestation?.digest || "root"}`;
      const appended = await appendEvent(ownerId, { eventType: BATCH252_ATTESTED_EVENT, stable, operationId, generation });
      latestAttestation = appended.event;
      if (!attestations.some(event => event.id === appended.event.id)) attestations.push(appended.event);
