    attestations = ledger.events.filter(event => BATCH252_EVENT_TYPES.includes(event.eventType))
      .sort((a, b) => a.generation - b.generation || a.sequence - b.sequence);
    const audit = await auditExternalBatch251LifecycleFinalizationReceiptAttestations(ownerId);
