    const latestAttestations = [...latestByReceipt.values()];
    const keyCutoffDetected = latestAttestations.some(event => event.stableBinding?.keyCutoffDetected === true
      || event.stableBinding?.signingKeyLifecycleBindingDigest !== currentKeyDigest);
    const keyCutoffRevalidated = latestAttestations.every(event => event.stableBinding?.signingKeyLifecycleBindingDigest === currentKeyDigest
      && (event.stableBinding?.keyCutoffDetected !== true || event.stableBinding?.keyCutoffRevalidated === true));
