    const lifecycleRenewal = ledger.events.filter(event => event.eventType === FINALIZATION_RECEIPT_BINDING_ATTESTATION_LIFECYCLE_EXTERNAL_ATTESTATION_LIFECYCLE_RENEWED_EVENT
      && event.stableBinding?.action === "renew").at(-1) || null;
