    if (finalized && !finalizationReceipt) findings.push({ code: "RECOVERY_GATE_FINALIZATION_RECEIPT_BINDING_ATTESTATION_LIFECYCLE_ATTESTATION_RECEIPT_FINALIZATION_RECEIPT_MISSING" });
    if (!latest && finalizationReceipt) findings.push({ code: "RECOVERY_GATE_FINALIZATION_RECEIPT_BINDING_ATTESTATION_LIFECYCLE_ATTESTATION_RECEIPT_EXTERNAL_ATTESTATION_MISSING" });
