    const chainInvalid = findings.some(item => /ATTESTATION_RECEIPT_.*(?:CHAIN_INVALID|RENEWAL_INVALID|REVOCATION_INVALID|SUPERSESSION_INVALID|FINALIZATION_INVALID|LIFECYCLE_EVENT_INVALID|FINALIZATION_RECEIPT_INVALID|REVOCATION_DESCENDANT_PRESENT)/.test(item.code || ""));
