    const keyBinding = await getCurrentKeyBinding(ownerId);
    const keyDigest = keyBinding?.bindingDigest || null;
    if (!DIGEST.test(keyDigest || "")) throw new AgenticError("RECOVERY_GATE_PROOF_CONTINUITY_KEY_BINDING_UNAVAILABLE", "Key lifecycle binding tidak tersedia", 409);
