    const supersessionEvents = events.filter(event => event.eventType === FINALIZATION_ATTESTATION_LIFECYCLE_RECEIPT_ATTESTATION_LIFECYCLE_SUPERSESSION_EVENT);
    const revokedEvents = events.filter(event => event.eventType === FINALIZATION_ATTESTATION_LIFECYCLE_RECEIPT_ATTESTATION_LIFECYCLE_REVOKED_EVENT);
