      finalizationCount: finalizations.length, missingFinalizationReceiptCount: missingReceipts.length, orphanReceiptCount, invalidSignatureCount,
      pendingChallengeIds, keyCutoffDetected, keyCutoffRevalidated, terminalRevocation: terminalRevocation
