    if (!DIGEST.test(keyDigest || "")) throw new AgenticError("RECOVERY_GATE_PROOF_CONTINUITY_KEY_BINDING_UNAVAILABLE",
      "Signing-key lifecycle binding tidak tersedia", 409);
    const sourceFinalizationReceiptId = target.stableBinding?.finalizationReceiptId || target.stableBinding?.sourceFinalizationReceiptId || null;
    const sourceFinalizationReceiptDigest = target.stableBinding?.finalizationReceiptDigest || target.stableBinding?.sourceFinalizationReceiptDigest || null;
    if (!sourceFinalizationReceiptId || !DIGEST.test(sourceFinalizationReceiptDigest || "")) throw new AgenticError(
      "RECOVERY_GATE_BATCH243_SOURCE_RECEIPT_INVALID", "Target attestation tidak memiliki finalization receipt binding", 409);
    const intents = ledger.events.filter(event => event.eventType === BATCH243_INTENT_EVENT);
    const generation = intents.length + 1;
    const createdAt = nowIso(clock), expiresAt = new Date(Date.parse(createdAt) + ttlMs).toISOString();
    const challengeId = `batch243-lifecycle-${randomBytes(16).toString("hex")}`;
