        throw new AgenticError("RECOVERY_GATE_BATCH247_LEDGER_CHANGED", "Ledger berubah sejak challenge disiapkan", 409);
      const [sourceAudit, checkpoint, keyBinding] = await Promise.all([
        auditExternalBatch245LifecycleFinalizationReceiptAttestations(ownerId),
        getFinalizationReceiptBindingAttestationLifecycleExternalAttestationFinalizationReceiptAttestationCheckpointState(ownerId),
        getCurrentKeyBinding(ownerId)]);
      if (sourceAudit.status !== "verified_current" || checkpoint.enabled && checkpoint.usableForCurrentDecision !== true)
        throw new AgenticError("RECOVERY_GATE_BATCH247_PRECONDITION_FAILED", "Source attestation dan checkpoint harus current", 409,
          { sourceAuditStatus: sourceAudit.status, checkpointStatus: checkpoint.status });
