    const unsigned = { id: challengeId, ownerId, kind: BATCH251_CHALLENGE_KIND, schemaVersion: 1, status: "prepared", action, reason,
      targetAttestationId: target.id, targetAttestationDigest: target.digest, targetAttestationGeneration: target.generation,
      sourceFinalizationReceiptId, sourceFinalizationReceiptDigest, targetLedgerHeadDigest: ledger.headDigest, targetLedgerCount: ledger.count,
      targetLedgerSnapshotDigest: sha256(canonical(ledger.events.map(event => event.digest))), preparedKeyBindingDigest: keyDigest,
      externalAttestationLifecycleGeneration: generation, createdAt, expiresAt, confirmationPhrase };
