    const receipts = ledger.events.filter(event => BATCH253_RECEIPT_EVENT_TYPES.includes(event.eventType));
    const snapshot = { schemaVersion: 1, domain: "cross_domain_batch252_external_attestation_lifecycle", ownerId, ledgerId: ledger.id,
      lifecycleEvents: lifecycleEvents.map(event => ({ id: event.id, digest: event.digest, generation: event.generation,
        eventType: event.eventType, operationId: event.operationId, challengeId: event.stableBinding?.challengeId || null,
        action: event.stableBinding?.action || null, targetAttestationId: event.stableBinding?.targetAttestationId || null,
        replacementAttestationId: event.stableBinding?.replacementAttestationId || null })),
      finalizationReceipts: receipts.map(event => ({ id: event.id, digest: event.digest, generation: event.generation,
        lifecycleFinalizationEventId: event.stableBinding?.lifecycleFinalizationEventId || null,
        lifecycleFinalizationEventDigest: event.stableBinding?.lifecycleFinalizationEventDigest || null,
        receiptBindingDigest: event.stableBinding?.receiptBindingDigest || null,
        previousReceiptId: event.stableBinding?.previousReceiptId || null, previousReceiptDigest: event.stableBinding?.previousReceiptDigest || null })) };
