    if (active.terminalRevocation) throw new AgenticError("RECOVERY_GATE_BATCH255_TERMINAL_REVOCATION",
      "External attestation sudah dicabut secara terminal", 409);
    if (active.chainInvalid) throw new AgenticError("RECOVERY_GATE_BATCH255_CHAIN_INVALID",
      "Replacement attestation tidak dapat diverifikasi", 409);
