    const currentKeyDigest = keyBinding?.bindingDigest || null, latest = receipts.at(-1)?.stableBinding || {};
    const keyCutoffDetected = Boolean(latest.receiptSigningKeyBindingDigest && latest.receiptSigningKeyBindingDigest !== currentKeyDigest) || latest.keyCutoffDetected === true;
    const keyCutoffRevalidated = latest.receiptSigningKeyBindingDigest === currentKeyDigest
      && (latest.keyCutoffDetected !== true || latest.keyCutoffRevalidated === true);
