        reasonDigest: sha256(challenge.reason), preparedKeyBindingDigest: challenge.preparedKeyBindingDigest,
        signingKeyLifecycleBindingDigest: keyDigest, keyCutoffDetected: keyDigest !== challenge.preparedKeyBindingDigest,
