    if (!Number.isSafeInteger(ttlMs) || ttlMs < 1000 || ttlMs > 60 * 60 * 1000)
      throw new AgenticError("RECOVERY_GATE_BATCH273_TTL_INVALID", "TTL challenge harus 1 detik hingga 1 jam", 400);
    const ledger = await readLedger(ownerId);
    if (ledger.status === "unhealthy") throw new AgenticError("RECOVERY_GATE_PROOF_CONTINUITY_LEDGER_UNHEALTHY",
      "Ledger tidak sehat; Batch 273 lifecycle ditolak", 409, { findings: ledger.findings });
    const [sourceAudit, lifecycleAudit, checkpoint, keyBinding] = await Promise.all([
      auditExternalBatch271LifecycleFinalizationReceiptAttestations(ownerId),
      auditBatch273ExternalAttestationLifecycle(ownerId),
      getFinalizationReceiptBindingAttestationLifecycleExternalAttestationFinalizationReceiptAttestationCheckpointState(ownerId),
      getCurrentKeyBinding(ownerId)]);
    if ([sourceAudit, lifecycleAudit].some(audit => audit.status === "unhealthy")) throw new AgenticError(
      "RECOVERY_GATE_BATCH273_SOURCE_UNHEALTHY", "Source attestation atau lifecycle chain tidak sehat", 409,
      { sourceFindings: sourceAudit.findings || [], lifecycleFindings: lifecycleAudit.findings || [] });
    if (sourceAudit.status !== "verified_current") throw new AgenticError("RECOVERY_GATE_BATCH273_SOURCE_NOT_CURRENT",
      "Batch 272 external attestation harus verified_current sebelum lifecycle mutation", 409, { status: sourceAudit.status });
    if (["decision_blocked", "stale", "recovery_required"].includes(lifecycleAudit.status)) throw new AgenticError(
      "RECOVERY_GATE_BATCH273_LIFECYCLE_NOT_CURRENT", "Selesaikan lifecycle recovery atau terminal revocation sebelum challenge baru", 409,
      { status: lifecycleAudit.status });
    if (checkpoint.enabled && checkpoint.usableForCurrentDecision !== true) throw new AgenticError(
      "RECOVERY_GATE_BATCH273_CHECKPOINT_NOT_CURRENT", "Independent checkpoint harus current sebelum lifecycle mutation", 409,
      { status: checkpoint.status, findings: checkpoint.findings || [] });
