        sourceFinalizationReceiptId: challenge.sourceFinalizationReceiptId, sourceFinalizationReceiptDigest: challenge.sourceFinalizationReceiptDigest,
        reasonDigest: sha256(challenge.reason), preparedKeyBindingDigest: challenge.preparedKeyBindingDigest,
