        challengeId: challenge.id, action: challenge.action, externalAttestationLifecycleGeneration: finalized.generation,
        targetAttestationId: challenge.targetAttestationId, targetAttestationDigest: challenge.targetAttestationDigest,
        sourceFinalizationReceiptId: challenge.sourceFinalizationReceiptId, sourceFinalizationReceiptDigest: challenge.sourceFinalizationReceiptDigest,
        intentEventId: intent.id, intentEventDigest: intent.digest, actionEventId: actionEvent.id, actionEventDigest: actionEvent.digest,
