    const finalizations = lifecycleEvents.filter(event => event.eventType === BATCH273_FINALIZED_EVENT).sort((a, b) => a.generation - b.generation || a.sequence - b.sequence);
    const receipts = ledger.events.filter(event => BATCH273_RECEIPT_EVENT_TYPES.includes(event.eventType)).sort((a, b) => a.generation - b.generation || a.sequence - b.sequence);
